using FamilyVeda.Application.Common;
using FamilyVeda.Application.Portal;
using FamilyVeda.Domain.Clinical;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.Infrastructure.Portal;

public sealed class JoinRequestService(AppDbContext dbContext, ICurrentUser currentUser) : IJoinRequestService
{
    public async Task<JoinRequestDto> CreateAsync(CreateJoinRequest request, CancellationToken cancellationToken)
    {
        if (currentUser.UserType != Domain.Common.UserType.FamilyUser)
        {
            throw new ForbiddenException();
        }

        var code = request.FamilyCode.Trim().ToUpperInvariant();
        var family = await dbContext.Families.SingleOrDefaultAsync(x => x.FamilyCode == code, cancellationToken)
            ?? throw new NotFoundException();

        if (await dbContext.Members.AnyAsync(x => x.FamilyId == family.Id && x.UserId == currentUser.UserId, cancellationToken))
        {
            throw new ConflictException("You are already a member of this family.");
        }

        if (await dbContext.FamilyJoinRequests.AnyAsync(x => x.FamilyId == family.Id && x.RequestingUserId == currentUser.UserId && x.Status == PortalRequestStatus.Pending, cancellationToken))
        {
            throw new ConflictException("You already have a pending join request for this family.");
        }

        var since = DateTimeOffset.UtcNow.AddHours(-1);
        var recentCount = await dbContext.FamilyJoinRequests.CountAsync(x => x.RequestingUserId == currentUser.UserId && x.CreatedAt >= since, cancellationToken);
        if (recentCount >= 5)
        {
            throw new ConflictException("Too many join requests. Try again later.");
        }

        if (string.IsNullOrWhiteSpace(request.RelationshipType) || request.RelationshipType.Trim().Length > 40)
        {
            throw new Application.Common.ValidationException(new Dictionary<string, string[]> { ["relationshipType"] = ["Relationship type is required and cannot exceed 40 characters."] });
        }

        var joinRequest = new FamilyJoinRequest
        {
            FamilyId = family.Id,
            RequestingUserId = currentUser.UserId,
            RelationshipType = request.RelationshipType.Trim(),
            Message = request.Message?.Trim()
        };
        dbContext.FamilyJoinRequests.Add(joinRequest);
        AddAudit("FAMILY_JOIN_REQUESTED", joinRequest.Id);
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(joinRequest, family.Id, cancellationToken);
    }

    public async Task<IReadOnlyList<JoinRequestDto>> GetForFamilyAsync(Guid familyId, string? status, CancellationToken cancellationToken)
    {
        await RequireHeadAsync(familyId, cancellationToken);
        var query = dbContext.FamilyJoinRequests.AsNoTracking().Where(x => x.FamilyId == familyId);
        if (!string.IsNullOrWhiteSpace(status) && Enum.TryParse<PortalRequestStatus>(status, true, out var parsed))
        {
            query = query.Where(x => x.Status == parsed);
        }

        var requests = await query.OrderByDescending(x => x.CreatedAt).ToListAsync(cancellationToken);
        var results = new List<JoinRequestDto>();
        foreach (var request in requests)
        {
            results.Add(await MapAsync(request, familyId, cancellationToken));
        }
        return results;
    }

    public async Task<IReadOnlyList<JoinRequestDto>> GetMineAsync(CancellationToken cancellationToken)
    {
        var requests = await dbContext.FamilyJoinRequests.AsNoTracking()
            .Where(x => x.RequestingUserId == currentUser.UserId)
            .OrderByDescending(x => x.CreatedAt)
            .ToListAsync(cancellationToken);
        var results = new List<JoinRequestDto>();
        foreach (var request in requests)
        {
            results.Add(await MapAsync(request, request.FamilyId, cancellationToken));
        }
        return results;
    }

    public async Task<JoinRequestDto> AcceptAsync(Guid id, CancellationToken cancellationToken)
    {
        var request = await dbContext.FamilyJoinRequests.SingleOrDefaultAsync(x => x.Id == id, cancellationToken) ?? throw new NotFoundException();
        await RequireHeadAsync(request.FamilyId, cancellationToken);
        if (request.Status != PortalRequestStatus.Pending)
        {
            throw new ConflictException("This request has already been resolved.");
        }

        var requestingUser = await dbContext.Users.SingleAsync(x => x.Id == request.RequestingUserId, cancellationToken);
        var member = new Member
        {
            FamilyId = request.FamilyId,
            UserId = requestingUser.Id,
            DisplayName = requestingUser.DisplayName,
            DateOfBirth = DateOnly.FromDateTime(DateTime.UtcNow).AddYears(-18),
            Role = Domain.Common.FamilyRole.AdultMember
        };
        dbContext.Members.Add(member);
        foreach (var category in Enum.GetValues<Domain.Common.ConsentCategory>())
        {
            dbContext.Consents.Add(new Consent { Member = member, Category = category });
        }

        request.Status = PortalRequestStatus.Accepted;
        request.RespondedAt = DateTimeOffset.UtcNow;
        request.RespondedByUserId = currentUser.UserId;
        AddAudit("FAMILY_JOIN_ACCEPTED", request.Id);
        AddNotification(requestingUser.Id, "FAMILY_JOIN_ACCEPTED", "Join request accepted", "Your request to join the family was accepted.", "/family");
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(request, request.FamilyId, cancellationToken);
    }

    public async Task<JoinRequestDto> DeclineAsync(Guid id, CancellationToken cancellationToken)
    {
        var request = await dbContext.FamilyJoinRequests.SingleOrDefaultAsync(x => x.Id == id, cancellationToken) ?? throw new NotFoundException();
        await RequireHeadAsync(request.FamilyId, cancellationToken);
        if (request.Status != PortalRequestStatus.Pending)
        {
            throw new ConflictException("This request has already been resolved.");
        }

        request.Status = PortalRequestStatus.Declined;
        request.RespondedAt = DateTimeOffset.UtcNow;
        request.RespondedByUserId = currentUser.UserId;
        AddAudit("FAMILY_JOIN_DECLINED", request.Id);
        AddNotification(request.RequestingUserId, "FAMILY_JOIN_DECLINED", "Join request declined", "Your request to join the family was declined.", "/family");
        await dbContext.SaveChangesAsync(cancellationToken);
        return await MapAsync(request, request.FamilyId, cancellationToken);
    }

    private async Task RequireHeadAsync(Guid familyId, CancellationToken cancellationToken)
    {
        var isHead = await dbContext.Families.AnyAsync(x => x.Id == familyId && x.CreatedByUserId == currentUser.UserId, cancellationToken);
        if (!isHead)
        {
            throw new NotFoundException();
        }
    }

    private async Task<JoinRequestDto> MapAsync(FamilyJoinRequest request, Guid familyId, CancellationToken cancellationToken)
    {
        var family = await dbContext.Families.AsNoTracking().SingleAsync(x => x.Id == familyId, cancellationToken);
        var requester = await dbContext.Users.AsNoTracking().SingleAsync(x => x.Id == request.RequestingUserId, cancellationToken);
        return new JoinRequestDto(request.Id, request.FamilyId, family.Name, requester.DisplayName, MaskEmail(requester.Email),
            request.RelationshipType, request.Message, request.Status, request.CreatedAt, request.RespondedAt);
    }

    private static string MaskEmail(string email)
    {
        var at = email.IndexOf('@');
        var first = at > 0 ? email[0] : 'a';
        return $"{first}***@example.invalid";
    }

    private void AddAudit(string eventType, Guid resourceId) => dbContext.AuditLogs.Add(new AuditLog
    {
        ActorUserId = currentUser.UserId,
        EventType = eventType,
        ResourceType = "FamilyJoinRequest",
        ResourceId = resourceId,
        Outcome = "SUCCESS",
        MetadataJson = "{}"
    });

    private void AddNotification(Guid userId, string type, string title, string body, string? linkPath) =>
        dbContext.PortalNotifications.Add(new PortalNotification { UserId = userId, Type = type, Title = title, Body = body, LinkPath = linkPath });
}
